  function flipCard(cls, front, back) {
    var d = document.createElement('div');
    d.className = 'fc ' + cls;
    d.setAttribute('role', 'button');
    d.tabIndex = 0;
    var inn = document.createElement('span');
    inn.className = 'fc-in';
    var f = document.createElement('div'); f.className = 'fc-f';
    var b = document.createElement('div'); b.className = 'fc-b';
    front(f); back(b);
    inn.appendChild(f); inn.appendChild(b); d.appendChild(inn);
    var busy = false;
    function flip() {
      if (busy) return;
      busy = true;
      inn.classList.add('half');
      setTimeout(function () {
        d.classList.toggle('on');
        inn.classList.remove('half');
        inn.classList.add('half2');
        void inn.offsetWidth;
        inn.classList.remove('half2');
        setTimeout(function () { busy = false; }, 200);
      }, 180);
    }
    d.addEventListener('click', flip);
    d.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); flip(); } });
    return d;
  }
