    var K = 3, pad = 8, w = x1 - x0 + 2 * pad, hh = y1 - y0 + 2 * pad + 30;
    var cvh = document.createElement('canvas');
    cvh.width = Math.ceil(w * K); cvh.height = Math.ceil(hh * K);
    var g = cvh.getContext('2d');
    g.scale(K, K); g.translate(pad - x0, pad - y0);
