    var lg = g.createLinearGradient(x0, y0, x1, y0 + (y1 - y0) * 0.8);
    lg.addColorStop(0, 'rgba(255,240,200,0.38)'); lg.addColorStop(0.5, 'rgba(255,240,200,0.08)'); lg.addColorStop(1, 'rgba(0,0,0,0.28)');
    g.fillStyle = lg; g.fillRect(x0 - 2, y0 - 2, x1 - x0 + 4, y1 - y0 + 4);
