        var hg = ctx.createRadialGradient(0, 0, 2, 0, 0, 44);
        hg.addColorStop(0, 'rgba(255,225,90,0.95)'); hg.addColorStop(0.45, 'rgba(255,214,80,0.45)'); hg.addColorStop(1, 'rgba(255,214,80,0)');
