    var inT = circuit.mask ? inTrack : function (x, y) { return inSegs(idx, x, y); };
    var base = progressOf(p.x, p.y, idx).s;
    var left = Math.max(1, botTarget(p) - p.shots);
    var lastOne = left <= 1;
